"""Student material for 6.º básico Matemática, OA 17 (suma de ángulos interiores de triángulos y cuadriláteros) y OA 18 (superficie de cubos y paralelepípedos en cm² y m²)."""
from __future__ import annotations

from student_content_ma06_b import L
